-- ============================================================================
-- Phase 2: Multi-tenancy migration
--
-- IMPORTANT — READ BEFORE RUNNING:
-- This was written by hand, not generated by `prisma migrate dev`, because
-- this sandbox has no network access to a live Postgres instance or to
-- Prisma's engine binaries. Before applying to any real database:
--
--   1. BACK UP the database first. This migration is not reversible as
--      written (no down-migration is provided).
--   2. Run it against a staging copy of production data first, not prod
--      directly.
--   3. After applying, run `npx prisma validate` and `npx prisma generate`
--      and confirm they succeed, then run the app's test suite.
--   4. If you'd rather have Prisma generate/verify this migration itself,
--      you can instead: (a) apply schema.prisma's changes, (b) run
--      `npx prisma migrate dev --create-only` to let Prisma generate its
--      own migration.sql, then (c) manually merge in the data-backfill
--      block below (Prisma will NOT write the backfill logic for you —
--      it only knows how to add/drop columns and constraints, not how to
--      populate them from existing rows).
--
-- Strategy used throughout: add columns NULLABLE first, backfill data,
-- THEN add NOT NULL/foreign-key/unique constraints. This is the standard
-- zero-downtime pattern and avoids the migration failing outright on a
-- database that already has rows (a plain `ADD COLUMN "clubId" TEXT NOT
-- NULL` would fail immediately on any table with existing data).
-- ============================================================================


-- ── 1. New enums ────────────────────────────────────────────────────────────

CREATE TYPE "ClubStatus" AS ENUM ('TRIAL', 'ACTIVE', 'SUSPENDED', 'CANCELLED');
CREATE TYPE "SaasPlanTier" AS ENUM ('STARTER', 'PRO', 'BUSINESS');
CREATE TYPE "PlatformSubscriptionStatus" AS ENUM ('TRIALING', 'ACTIVE', 'PAST_DUE', 'CANCELED', 'SUSPENDED');

-- Postgres requires adding enum values outside of a transaction in older
-- versions; on PG12+ this works fine inside `prisma migrate deploy`'s
-- transaction. If your Postgres is older than 12, run this single line
-- separately before the rest of the migration.
ALTER TYPE "Role" ADD VALUE 'SUPER_ADMIN';


-- ── 2. New tables: clubs, saas_plans, club_subscriptions ───────────────────

CREATE TABLE "clubs" (
    "id" TEXT NOT NULL,
    "slug" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "status" "ClubStatus" NOT NULL DEFAULT 'TRIAL',
    "customDomain" TEXT,
    "trialEndsAt" TIMESTAMP(3),
    "suspendedAt" TIMESTAMP(3),
    "suspendedReason" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "clubs_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "clubs_slug_key" ON "clubs"("slug");
CREATE UNIQUE INDEX "clubs_customDomain_key" ON "clubs"("customDomain");
CREATE INDEX "clubs_status_idx" ON "clubs"("status");

CREATE TABLE "saas_plans" (
    "id" TEXT NOT NULL,
    "tier" "SaasPlanTier" NOT NULL,
    "name" TEXT NOT NULL,
    "priceMonthly" DOUBLE PRECISION NOT NULL,
    "currency" TEXT NOT NULL DEFAULT 'USD',
    "limits" JSONB NOT NULL,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "saas_plans_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "saas_plans_tier_key" ON "saas_plans"("tier");

CREATE TABLE "club_subscriptions" (
    "id" TEXT NOT NULL,
    "clubId" TEXT NOT NULL,
    "planId" TEXT NOT NULL,
    "status" "PlatformSubscriptionStatus" NOT NULL DEFAULT 'TRIALING',
    "trialEndsAt" TIMESTAMP(3),
    "currentPeriodStart" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "currentPeriodEnd" TIMESTAMP(3),
    "cancelAtPeriodEnd" BOOLEAN NOT NULL DEFAULT false,
    "canceledAt" TIMESTAMP(3),
    "providerCustomerId" TEXT,
    "providerSubscriptionId" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "club_subscriptions_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "club_subscriptions_clubId_key" ON "club_subscriptions"("clubId");
CREATE INDEX "club_subscriptions_planId_idx" ON "club_subscriptions"("planId");
CREATE INDEX "club_subscriptions_status_idx" ON "club_subscriptions"("status");
ALTER TABLE "club_subscriptions" ADD CONSTRAINT "club_subscriptions_clubId_fkey" FOREIGN KEY ("clubId") REFERENCES "clubs"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "club_subscriptions" ADD CONSTRAINT "club_subscriptions_planId_fkey" FOREIGN KEY ("planId") REFERENCES "saas_plans"("id") ON DELETE RESTRICT ON UPDATE CASCADE;


-- ── 3. Seed the SaaS plan catalog + one default Club for existing data ─────
