UPDATE "page_content" SET "clubId" = 'default-gym';
UPDATE "role_permissions" SET "clubId" = 'default-gym';
UPDATE "member_reports" SET "clubId" = 'default-gym';


-- ── 6. Enforce NOT NULL now that every row has a value ─────────────────────
-- users.clubId stays NULLABLE (SUPER_ADMIN accounts have none). Every other
-- table below is gym-owned and always belongs to exactly one Club.

ALTER TABLE "membership_plans" ALTER COLUMN "clubId" SET NOT NULL;
ALTER TABLE "subscriptions" ALTER COLUMN "clubId" SET NOT NULL;
ALTER TABLE "payments" ALTER COLUMN "clubId" SET NOT NULL;
ALTER TABLE "weekly_plans" ALTER COLUMN "clubId" SET NOT NULL;
ALTER TABLE "sessions" ALTER COLUMN "clubId" SET NOT NULL;
ALTER TABLE "coaches" ALTER COLUMN "clubId" SET NOT NULL;
