ALTER TABLE "attendances" ALTER COLUMN "clubId" SET NOT NULL;
ALTER TABLE "notifications" ALTER COLUMN "clubId" SET NOT NULL;
ALTER TABLE "posts" ALTER COLUMN "clubId" SET NOT NULL;
ALTER TABLE "promotions" ALTER COLUMN "clubId" SET NOT NULL;
ALTER TABLE "gym_settings" ALTER COLUMN "clubId" SET NOT NULL;
