-- ── 8. Drop old GLOBAL unique constraints that are now wrong, add scoped ones ─
-- Each of these previously prevented two different gyms from independently
-- using the same code/number/key. Find your actual constraint names first —
-- Prisma's default naming is assumed below (`prisma migrate diff` against
-- your real DB will tell you if they differ):

ALTER TABLE "users" DROP CONSTRAINT IF EXISTS "users_email_key";
CREATE UNIQUE INDEX "users_clubId_email_key" ON "users"("clubId", "email");
-- Composite unique above does NOT stop two SUPER_ADMIN rows (clubId IS NULL)
-- from sharing an email, because Postgres treats NULL <> NULL even inside a
-- unique index. This partial index covers exactly that gap:
CREATE UNIQUE INDEX "users_platform_email_key" ON "users"("email") WHERE "clubId" IS NULL;
CREATE INDEX "users_clubId_idx" ON "users"("clubId");
CREATE INDEX "users_clubId_role_idx" ON "users"("clubId", "role");

ALTER TABLE "weekly_plans" DROP CONSTRAINT IF EXISTS "weekly_plans_weekStart_weekEnd_key";
CREATE UNIQUE INDEX "weekly_plans_clubId_weekStart_weekEnd_key" ON "weekly_plans"("clubId", "weekStart", "weekEnd");
CREATE INDEX "weekly_plans_clubId_idx" ON "weekly_plans"("clubId");

ALTER TABLE "membership_cards" DROP CONSTRAINT IF EXISTS "membership_cards_cardNumber_key";
CREATE UNIQUE INDEX "membership_cards_clubId_cardNumber_key" ON "membership_cards"("clubId", "cardNumber");
CREATE INDEX "membership_cards_clubId_idx" ON "membership_cards"("clubId");

ALTER TABLE "promotions" DROP CONSTRAINT IF EXISTS "promotions_code_key";
CREATE UNIQUE INDEX "promotions_clubId_code_key" ON "promotions"("clubId", "code");
CREATE INDEX "promotions_clubId_idx" ON "promotions"("clubId");

ALTER TABLE "page_content" DROP CONSTRAINT IF EXISTS "page_content_pageKey_key";
CREATE UNIQUE INDEX "page_content_clubId_pageKey_key" ON "page_content"("clubId", "pageKey");
CREATE INDEX "page_content_clubId_idx" ON "page_content"("clubId");

ALTER TABLE "role_permissions" DROP CONSTRAINT IF EXISTS "role_permissions_role_key_key";
CREATE UNIQUE INDEX "role_permissions_clubId_role_key_key" ON "role_permissions"("clubId", "role", "key");
CREATE INDEX "role_permissions_clubId_idx" ON "role_permissions"("clubId");

-- gym_settings had no unique key before (singleton by convention, id was
-- always the literal string 'singleton') — clubId is now its 1:1 key.
-- If your existing row's id is literally 'singleton', that's fine, Prisma
-- doesn't care what the primary key value is, only that clubId is unique:
CREATE UNIQUE INDEX "gym_settings_clubId_key" ON "gym_settings"("clubId");

-- Remaining straightforward indexes:
CREATE INDEX "membership_plans_clubId_idx" ON "membership_plans"("clubId");
CREATE INDEX "subscriptions_clubId_idx" ON "subscriptions"("clubId");
CREATE INDEX "payments_clubId_idx" ON "payments"("clubId");
CREATE INDEX "sessions_clubId_idx" ON "sessions"("clubId");
CREATE INDEX "coaches_clubId_idx" ON "coaches"("clubId");
CREATE INDEX "user_sessions_clubId_idx" ON "user_sessions"("clubId");
CREATE INDEX "attendances_clubId_idx" ON "attendances"("clubId");
CREATE INDEX "notifications_clubId_idx" ON "notifications"("clubId");
CREATE INDEX "posts_clubId_createdAt_idx" ON "posts"("clubId", "createdAt");
CREATE INDEX "member_reports_clubId_idx" ON "member_reports"("clubId");
CREATE INDEX "activity_logs_clubId_idx" ON "activity_logs"("clubId");


